import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA code for elementwise multiplication and clamp
custom_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_mul_kernel(const float* __restrict__ input,
                                       const float* __restrict__ scale,
                                       float* __restrict__ output,
                                       int batches, int channels, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = batches * channels * height * width;
    if (idx < total_size) {
        int w_i = idx % width;
        int h_i = (idx / width) % height;
        int c_i = (idx / (width * height)) % channels;
        output[idx] = input[idx] * scale[c_i];
    }
}

torch::Tensor elementwise_mul_cuda(torch::Tensor input, torch::Tensor scale) {
    auto sizes = input.sizes();
    int batches = sizes[0];
    int channels = sizes[1];
    int height = sizes[2];
    int width = sizes[3];

    auto output = torch::zeros_like(input);

    int total_size = batches * channels * height * width;
    int block_size = 256;
    int grid_size = (total_size + block_size - 1) / block_size;

    elementwise_mul_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        scale.data_ptr<float>(),
        output.data_ptr<float>(),
        batches, channels, height, width
    );

    return output;
}

__global__ void clamp_kernel(const float* __restrict__ input,
                             float* __restrict__ output,
                             int size,
                             float min_val, float max_val) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        if (val < min_val) val = min_val;
        else if (val > max_val) val = max_val;
        output[idx] = val;
    }
}

torch::Tensor clamp_cuda(torch::Tensor input, float min_val, float max_val) {
    auto output = torch::zeros_like(input);
    int size = input.numel();

    int block_size = 256;
    int grid_size = (size + block_size - 1) / block_size;

    clamp_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        size,
        min_val, max_val
    );

    return output;
}
"""

cpp_declaration = r"""
torch::Tensor elementwise_mul_cuda(torch::Tensor input, torch::Tensor scale);
torch::Tensor clamp_cuda(torch::Tensor input, float min_val, float max_val);
"""

# Compile and load the custom operators
custom_ops = load_inline(
    name="custom_ops",
    cpp_sources=cpp_declaration,
    cuda_sources=custom_source,
    functions=["elementwise_mul_cuda", "clamp_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs convolution, group normalization,
    custom CUDA scaling, max pooling, and custom CUDA clamping.
    """
    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        num_groups,
        scale_shape,
        maxpool_kernel_size,
        clamp_min,
        clamp_max
    ):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.group_norm = nn.GroupNorm(num_groups, out_channels)
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.maxpool = nn.MaxPool2d(kernel_size=maxpool_kernel_size)
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max

    def forward(self, x):
        x = self.conv(x)
        x = self.group_norm(x)
        x = custom_ops.elementwise_mul_cuda(x, self.scale)
        x = self.maxpool(x)
        x = custom_ops.clamp_cuda(x, self.clamp_min, self.clamp_max)
        return x

